/* ---- upstream x16r.cu:1121-1757, patched at the boundary ---- */

static int avian_no_final(void)
{
        static int cached = -1;
        if (cached < 0)
        {
                const char *e = getenv("AVIAN_GPU_NO_FINAL");
                cached = (e && *e && *e != '0') ? 1 : 0;
                if (cached)
                        applog(LOG_NOTICE, "GPU: AVIAN_GPU_NO_FINAL is set; the last "
                                           "stage runs the plain kernel and candidates "
                                           "come from a d_hash scan");
        }
        return cached;
}


/* Diagnostics only. Left unset by the miner, the stage bisect turns itself
 * off rather than comparing against nothing and reporting agreement. */
static avian_cuda_hash_n_fn  avian_diag_hash_n  = NULL;
static avian_cuda_prehash_fn avian_diag_prehash = NULL;

extern "C" AVIAN_CUDA_API void avian_cuda_set_diagnostics(avian_cuda_hash_n_fn hash_n,
                                                          avian_cuda_prehash_fn prehash)
{
        avian_diag_hash_n  = hash_n;
        avian_diag_prehash = prehash;
}

#define AVIAN_TRACE_SAMPLES 256

static int avian_trace_all(void)
{
        static int cached = -1;
        if (cached < 0)
        {
                const char *e = getenv("AVIAN_GPU_TRACE_ALL");
                cached = (e && *e && *e != '0') ? 1 : 0;
                if (cached && !avian_no_final())
                {
                        applog(LOG_ERR, "GPU: AVIAN_GPU_TRACE_ALL needs "
                                        "AVIAN_GPU_NO_FINAL=1, so the last stage's "
                                        "hash reaches d_hash");
                        cached = 0;
                }
                if (cached && !avian_diag_hash_n)
                {
                        applog(LOG_ERR, "GPU: the stage profile needs the miner's "
                                        "verifier, which this build did not hand over");
                        cached = 0;
                }
                if (cached)
                        applog(LOG_NOTICE, "GPU: profiling every stage of one batch, "
                                           "up to %d threads sampled",
                                           AVIAN_TRACE_SAMPLES);
        }
        return cached;
}

static int avian_trace_stages(void)
{
        static int cached = -2;
        if (cached == -2)
        {
                const char *e = getenv("AVIAN_GPU_TRACE_STAGES");
                cached = (e && *e) ? atoi(e) : 0;
                if (cached < 1 || cached > 16) cached = 0;
                if (cached == 16 && !avian_no_final())
                {
                        applog(LOG_ERR, "GPU: AVIAN_GPU_TRACE_STAGES=16 needs "
                                        "AVIAN_GPU_NO_FINAL=1, or d_hash is a stage "
                                        "short and every sample differs for nothing");
                        cached = 0;
                }
                /* The same check AVIAN_GPU_TRACE_ALL makes, and its absence
                 * here was not a missing message but a crash: the comparison
                 * calls straight through these pointers, so a build that did
                 * not hand them over dumped core instead of saying so. */
                if (cached && (!avian_diag_hash_n || !avian_diag_prehash))
                {
                        applog(LOG_ERR, "GPU: the stage bisect needs the miner's "
                                        "verifier, which this build did not hand over");
                        cached = 0;
                }
                if (cached)
                        applog(LOG_NOTICE, "GPU: stage bisect on, stopping after %d "
                                           "kernel(s), up to %d threads sampled per "
                                           "batch", cached, AVIAN_TRACE_SAMPLES);
        }
        return cached;
}

/* Compares the device's d_hash against the CPU chain truncated to the same
 * number of stages, for the nonces the device actually used. Thread t held
 * nonce start + t, because the 80-byte kernel is launched with startNonce =
 * pdata[19] and start is a copy of it taken in the same batch.
 *
 * Returns the number of sampled threads that differed, or -1 if the sample
 * had to be abandoned. */
static int avian_trace_compare(int thr_id, int dev_id, int stages,
                               uint32_t *d_hash_p, uint32_t *endiandata,
                               uint32_t *pdata, const char *order,
                               uint32_t start, uint32_t threads, int quiet)
{
        uint32_t hdr[20], cpu[16], gpu[16], cpu_first[16], gpu_first[16];
        uint32_t stride = threads / AVIAN_TRACE_SAMPLES;
        uint32_t first_t = 0;
        int bad = 0, first = -1, taken = 0;

        if (stride == 0) stride = 1;
        /* x16r_hash_generic takes the order as an argument, but x16r_prehash
         * reads the global the normal verification path uses, so the two
         * cannot disagree here in a way they would not in production. */
        memcpy(hdr, endiandata, 80);

        for (int j = 0; j < AVIAN_TRACE_SAMPLES; j++)
        {
                /* Last sample is pinned to the final thread, so the end of
                 * the batch is always covered however the stride divides. */
                uint32_t t = (j == AVIAN_TRACE_SAMPLES - 1)
                             ? threads - 1 : (uint32_t)j * stride;
                if (t >= threads) break;

                if (cudaMemcpy(gpu, d_hash_p + (size_t)t * 16, 64,
                               cudaMemcpyDeviceToHost) != cudaSuccess)
                {
                        applog(LOG_WARNING, "GPU #%d: trace copy failed", dev_id);
                        return -1;
                }
                be32enc(&hdr[19], start + t);
                avian_diag_prehash(hdr, pdata, order);
                /* Returns 0 without writing when a new job lands mid-chain.
                 * Comparing then would be noise, so abandon the sample. */
                if (!avian_diag_hash_n(cpu, hdr, thr_id, order, stages))
                        return -1;
                taken++;
                if (memcmp(cpu, gpu, 64) != 0)
                {
                        if (first < 0)
                        {
                                first = j;
                                first_t = t;
                                memcpy(cpu_first, cpu, 64);
                                memcpy(gpu_first, gpu, 64);
                        }
                        bad++;
                }
        }

        if (!quiet || bad)
                applog(bad ? LOG_WARNING : LOG_INFO,
                       "GPU #%d: TRACE stage %2d of %s: %3d/%d differ (stride %u of %u)",
                       dev_id, stages, order, bad, taken, stride, threads);
        if (first >= 0 && !quiet)
                applog(LOG_WARNING,
                       "GPU #%d:   first at thread %u (nonce %08x) gpu %08x%08x "
                       "cpu %08x%08x",
                       dev_id, first_t, start + first_t,
                       gpu_first[0], gpu_first[1], cpu_first[0], cpu_first[1]);
        return bad;
}


/* Run one chain order regardless of what the header derives.

   A chain-dependent fault can only be studied on a chain that occurs, and
   X16RT picks the chain from ntime, so a failing order recurs when it
   recurs and not when the instrument is ready. Forcing it makes the bisect
   a one-shot experiment rather than a stakeout.

   The override lands on hashOrder, which both the device chain and the CPU
   chain avian_trace_compare checks it against read, so the two stay
   consistent and a difference means the kernels rather than the override.

   Shares from a forced batch are nonsense by construction, because the
   order no longer matches the header the pool will judge. Diagnostics
   only, and loud about it. */
static const char *avian_force_order(void)
{
        static const char *cached = (const char *)-1;

        if (cached == (const char *)-1)
        {
                const char *e = getenv("AVIAN_GPU_FORCE_ORDER");
                cached = NULL;
                if (e && *e)
                {
                        /* Hand-rolled so this needs no ctype.h or string.h,
                           and so the generated file gains no include the
                           generators would have to anchor on. */
                        const char *p = e;
                        int n = 0, ok = 1;
                        while (*p)
                        {
                                char c = *p++;
                                if (!((c >= '0' && c <= '9') ||
                                      (c >= 'a' && c <= 'f') ||
                                      (c >= 'A' && c <= 'F')))
                                        ok = 0;
                                n++;
                        }
                        if (n != 16) ok = 0;
                        if (!ok)
                                applog(LOG_ERR, "GPU: AVIAN_GPU_FORCE_ORDER wants 16 "
                                                "hex digits, so %s is ignored", e);
                        else
                        {
                                cached = e;
                                applog(LOG_WARNING, "GPU: forcing chain order %s for "
                                                    "every batch; shares from this run "
                                                    "are invalid by construction", e);
                        }
                }
        }
        return cached;
}


/* Read the pending CUDA error, say which phase of the batch left it, and
 * then shut up about it.
 *
 * A CUDA error is sticky until something reads it, and almost nothing in
 * the vendored kernels does. The one exception is skein512_cpu_setBlock_80,
 * which calls cudaGetLastError() and aborts on whatever it finds, so an
 * error left by any batch killed the miner the next time SKEIN happened to
 * lead the chain. Reading it here keeps that from happening and names the
 * phase responsible.
 *
 * Capped deliberately. This fires every batch, which at a few hundred
 * batches a second buries every other line in the log and is worse than the
 * silence it replaced. */
static void avian_report(int dev_id, const char *phase, cudaError_t err)
{
        static int complained = 0;

        if (complained < 3)
        {
                applog(LOG_ERR, "GPU #%d: %s left \"%s\"",
                       dev_id, phase, cudaGetErrorString(err));
                if (++complained == 3)
                        applog(LOG_ERR, "GPU #%d: further CUDA errors will not "
                                        "be reported", dev_id);
        }
}

static void avian_phase_check(int dev_id, const char *phase)
{
        cudaError_t err = cudaGetLastError();

        if (err != cudaSuccess)
                avian_report(dev_id, phase, err);
}

/* Forces anything still in flight to complete before judging it. A peek
 * with cudaGetLastError() alone cannot see a failure that has not surfaced
 * yet, which is how a bad copy got attributed to a kernel that ran later. */
static void avian_sync_check(int dev_id, const char *phase)
{
        cudaError_t err = cudaDeviceSynchronize();

        if (err == cudaSuccess)
                err = cudaGetLastError();
        if (err != cudaSuccess)
                avian_report(dev_id, phase, err);
}

static void avian_batch_end(int dev_id)
{
        /* Capture the synchronise's own return. A kernel launch failure is
         * asynchronous: it is not visible at the launch, and it is
         * cudaDeviceSynchronize that reports it. Ignoring this return was
         * why the phase checks all came back clean while the error was
         * plainly reaching skein512_cpu_setBlock_80 later. */
        cudaError_t err = cudaDeviceSynchronize();

        if (err != cudaSuccess)
                avian_report(dev_id, "the batch's kernels", err);
        else
                avian_phase_check(dev_id, "the candidate search");
}

/* With AVIAN_GPU_SYNC_EACH_STAGE set, synchronise after every stage so an
 * asynchronous launch failure is attributed to the kernel that caused it
 * rather than to whatever happens to synchronise next. Far too slow to mine
 * with, which is why it is off unless asked for. */
static int avian_sync_each_stage(void)
{
        static int cached = -1;

        if (cached < 0)
        {
                const char *e = getenv("AVIAN_GPU_SYNC_EACH_STAGE");
                cached = (e && *e && *e != '0') ? 1 : 0;
        }
        return cached;
}

static void avian_stage_check(int dev_id, int stage, const char *name)
{
        cudaError_t err;

        if (!avian_sync_each_stage())
                return;
        err = cudaDeviceSynchronize();
        if (err == cudaSuccess)
                err = cudaGetLastError();
        if (err != cudaSuccess)
        {
                char what[64];
                snprintf(what, sizeof(what), "stage %d (%s)", stage, name);
                avian_report(dev_id, what, err);
        }
}

/* One batch of nonces. See avian-cuda-api.h for why the seam is here. */
extern "C" AVIAN_CUDA_API int avian_cuda_scan_batch( const avian_cuda_job *job,
                                                     uint32_t *out_nonces,
                                                     int max_out,
                                                     uint32_t *throughput_used )
{
        const int thr_id = job->thr_id;
        /* Copied rather than aliased: the kernels only read the header, and a
         * local copy means nothing here can scribble on the miner's work. */
        uint32_t _ALIGN(64) pdata_copy[20];
        uint32_t _ALIGN(64) ptarget_copy[8];
        uint32_t *pdata = pdata_copy;
        uint32_t *ptarget = ptarget_copy;
        uint32_t nonce0 = UINT32_MAX, nonce1 = UINT32_MAX;
        const int dev_id = device_map[thr_id];
        uint64_t hashes_done_local = 0;
        uint64_t *hashes_done = &hashes_done_local;

        /* A CUDA error is sticky until something reads it, and almost
         * nothing in the vendored kernels does. The one exception is
         * skein512_cpu_setBlock_80, which calls cudaGetLastError() and
         * aborts the miner on whatever it finds, so an error left by an
         * earlier batch killed the process the next time SKEIN happened to
         * lead the chain. Read it here, report it, and start clean, so the
         * error is attributed to the batch that caused it rather than to an
         * unrelated kernel one epoch in sixteen later. */
        avian_phase_check(dev_id, "a previous batch");

        memcpy(pdata_copy, job->data, sizeof(pdata_copy));
        memcpy(ptarget_copy, job->target, sizeof(ptarget_copy));
        pdata[19] = job->start_nonce;
        const uint32_t first_nonce = pdata[19];
        const uint32_t max_nonce = job->max_nonce;

	if (job->benchmark)
       	{
                ((uint32_t*)ptarget)[7] = 0x0ff;
//              ((uint32_t*)pdata)[1] = 0xF9E9EA98;
//              ((uint32_t*)pdata)[2] = 0x76543210;
                ((uint32_t*)pdata)[1] = 0x88888888;
                ((uint32_t*)pdata)[2] = 0x88888888;
        }

        uint32_t _ALIGN(64) endiandata[20];
        uint32_t _ALIGN(64) timeHash[8];

        for (int k = 0; k < 19; k++)
                be32enc(&endiandata[k], pdata[k]);

        uint32_t masked_ntime = endiandata[17] & 0xffffff80;
        /* The miner derives the chain and hands it over. Deriving it here as
         * well would put a consensus-critical rule on both sides of an ABI,
         * where the two could disagree and only one of them is tested. */
        (void)masked_ntime;
        (void)timeHash;
        memcpy(hashOrder, job->order, 17);
        hashOrder[16] = '\0';
        /* Diagnostics: see avian_force_order. */
        {
                const char *forced = avian_force_order();
                if (forced) memcpy(hashOrder, forced, 16);
        }
        if (s_ntime != masked_ntime) {
                s_ntime = masked_ntime;
        }

        uint32_t default_throughput=1<<19;
        bool splitsimd = true;
        bool merge = false;
        if ((strstr(device_name[dev_id], "1060")) || (strstr(device_name[dev_id], "P106")))
        {
                default_throughput = (1 << 21);
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "970") || (strstr(device_name[dev_id], "980"))))
        {
                default_throughput = (1 << 21);
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "1050")))
        {
                default_throughput = 1 << 20;
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "950")))
        {
                default_throughput = 1 << 20;
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "960")))
        {
                default_throughput = 1 << 20;
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "750")))
        {
                default_throughput = 1 << 20;
                splitsimd = false;
        }
        else if ((strstr(device_name[dev_id], "166")) || (strstr(device_name[dev_id], "20")))
        {
                default_throughput = (1 << 24); //53686272; //1 << 20
                merge = true;
        }
        else if (strstr(device_name[dev_id], "1070") || (strstr(device_name[dev_id], "P104")))
        {
                default_throughput = (1 << 24); //53686272; //1 << 20
                merge = true;
        }
        else if ((strstr(device_name[dev_id], "1080 Ti")) || (strstr(device_name[dev_id], "1080")) || (strstr(device_name[dev_id], "P102")))
        {
                default_throughput = (1 << 24); //53686272; //1 << 20
                merge = true;
        }
        uint32_t throughput = cuda_default_throughput(thr_id, default_throughput);

        if (throughput > (1<<22)) splitsimd = true;

        if (init[thr_id])
        {
                throughput = min(throughput, max_nonce - first_nonce);
        }
        throughput &= 0xFFFFFF00; //multiples of 128 due to cubehash_shavite & simd_echo kernels
        /* The mask sends a range shorter than 256 nonces to zero, and
         * then `pdata[19] += throughput` below cannot advance and the
         * do-loop spins for ever on empty kernel launches. A caller
         * asking for a handful of nonces, as --avian-selftest does, hits
         * this. 256 is what the mask's own granularity implies. */
        if (throughput < 0x100) throughput = 0x100;

        if (!init[thr_id])
        {

                cudaSetDevice(device_map[thr_id]);
                if (opt_cudaschedule == -1 && gpu_threads == 1)
                {
                        /* No cudaDeviceReset() here: see make-dll-driver.py.
                         * It would tear down the context this library's own
                         * caller already set up. */
                        cudaSetDeviceFlags(cudaDeviceScheduleBlockingSync);
                }

                gpulog(LOG_INFO, thr_id, "%s Intensity: %g ", device_name[dev_id], throughput2intensity(throughput));


                quark_blake512_cpu_init(thr_id, throughput);
                quark_bmw512_cpu_init(thr_id, throughput);
                quark_groestl512_cpu_init(thr_id, throughput);
                quark_skein512_cpu_init(thr_id, throughput);
                quark_jh512_cpu_init(thr_id, throughput);
                quark_keccak512_cpu_init(thr_id, throughput);
                x11_shavite512_cpu_init(thr_id, throughput);
                if (splitsimd)
                {
                        x11_simd512_cpu_init(thr_id, (throughput >> 4));
                }
                else
                {
                        x11_simd512_cpu_init(thr_id, (throughput));
                }
                x13_hamsi512_cpu_init(thr_id, throughput);
                x16_fugue512_cpu_init(thr_id, throughput);
                x15_whirlpool_cpu_init(thr_id, throughput, 0);
                x16_whirlpool512_init(thr_id, throughput);


                x11_luffa512_cpu_init(thr_id, throughput); // 64
                x16_echo512_cuda_init(thr_id, throughput);
                /* x13_fugue512_cpu_init is not called: it only bound a
                 * texture, and x13_fugue512_cpu_hash_64_sp, which is what
                 * this chain uses, reads its own __device__ table. */
                x16_fugue512_cpu_init(thr_id, throughput);
                x14_shabal512_cpu_init(thr_id, throughput);


                CUDA_CALL_OR_RET_X(cudaMalloc(&d_hash[thr_id], (size_t) 64 * throughput), 0);
                CUDA_SAFE_CALL(cudaMalloc(&d_resNonce[thr_id], 2 * sizeof(uint32_t)));

                cuda_check_cpu_init(thr_id, throughput);
                sleep(2);
                init[thr_id] = true;
        }


        cuda_check_cpu_setTarget(ptarget);
        avian_sync_check(dev_id, "the target upload");

        char elem = hashOrder[0];
        const uint8_t algo80 = elem >= 'A' ? elem - 'A' + 10 : elem - '0';

        /* Measured wrong, so not worth the card's time: a few MH/s of shares
         * that count beats forty of shares that do not. Remove this once the
         * 80-byte SIMD kernel is fixed. */

        switch (algo80)
        {
                case BLAKE:
                        quark_blake512_cpu_setBlock_80(thr_id, endiandata);
                        break;
                case BMW:
                        quark_bmw512_cpu_setBlock_80(endiandata);
                        break;
                case GROESTL:
                        groestl512_setBlock_80(thr_id, endiandata);
                        break;
                case JH:
                        jh512_setBlock_80(thr_id, endiandata);
                        break;
                case KECCAK:
                        keccak512_setBlock_80(thr_id, endiandata);
                        break;
                case SKEIN:
                        skein512_cpu_setBlock_80((void*)endiandata);
                        break;
                case LUFFA:
                        qubit_luffa512_cpu_setBlock_80_alexis((void*)endiandata);
                        break;
                case CUBEHASH:
                        cubehash512_setBlock_80(thr_id, endiandata);
                        break;
                case SHAVITE:
                        x16_shavite512_setBlock_80((void*)endiandata);
                        break;
                case SIMD:
                        x16_simd512_setBlock_80((void*)endiandata);
                        break;
                case ECHO:
                        x16_echo512_setBlock_80((void*)endiandata);
                        break;
                case HAMSI:
                        x16_hamsi512_setBlock_80((uint64_t*)endiandata);
                        break;
                case FUGUE:
                        x16_fugue512_setBlock_80((void*)pdata);
                        break;
                case SHABAL:
                        x16_shabal512_setBlock_80((void*)endiandata);
                        break;
                case WHIRLPOOL:
                        x16_whirlpool512_setBlock_80((void*)endiandata);
                        break;
                case SHA512:
                        x16_sha512_setBlock_80(endiandata);
                        break;
                default: {
                        if (!thr_id)
                                applog(LOG_WARNING, "kernel %s %c unimplemented, order %s", algo_strings[algo80], elem, hashOrder);
                        s_implemented = false;
                        sleep(5);
                        return -1;
                }
        }


        int warn = 0;

        {
                avian_phase_check(dev_id, "device setup");
                int order = 0;
                CUDA_SAFE_CALL(cudaMemset(d_resNonce[thr_id], 0xFFFFFFFF, 2 * sizeof(uint32_t)));
                /* Cleared with the device-side copy it mirrors. Left
                 * alone, a pass that finds nothing still sees the
                 * previous pass's nonce here and would offer it again. */
                nonce0 = UINT32_MAX;
                nonce1 = UINT32_MAX;

                uint32_t start = pdata[19];
                //uint32_t foundNonce;
                bool addstart = false;

                // Hash with CUDA
                switch (algo80)
                {
                        case BLAKE:
                                quark_blake512_cpu_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case BMW:
                                quark_bmw512_cpu_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id], order++);
                                break;
                        case GROESTL:
                                groestl512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case JH:
                                jh512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case KECCAK:
                                keccak512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case SKEIN:
                                skein512_cpu_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id], 1); order++;
                                break;
                        case LUFFA:
                                qubit_luffa512_cpu_hash_80_alexis(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case CUBEHASH:
                                cubehash512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case SHAVITE:
                                x16_shavite512_cpu_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id], order++);
                                break;
                        case SIMD:
                                x16_simd512_cuda_hash_80_sp(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case ECHO:
                                x16_echo512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case HAMSI:
                                x16_hamsi512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case FUGUE:
                                x16_fugue512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case SHABAL:
                                x16_shabal512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case WHIRLPOOL:
                                x16_whirlpool512_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                        case SHA512:
                                x16_sha512_cuda_hash_80(thr_id, throughput, pdata[19], d_hash[thr_id]); order++;
                                break;
                }
                uint8_t algo;


                for (int i = 1; i < 16; i++)
                {
                        /* At loop index i, exactly i kernels have run. In the
                         * all-stage profile the comparison is taken and the
                         * chain carries on, so one batch yields every stage
                         * for one chain order. In single-stage mode we return
                         * rather than break, to keep a partial chain out of
                         * the candidate path. */
                        if (avian_trace_all())
                                avian_trace_compare(thr_id, dev_id, i, d_hash[thr_id],
                                                    endiandata, pdata, hashOrder, start,
                                                    throughput, 0);
                        else if (avian_trace_stages() == i)
                        {
                                avian_trace_compare(thr_id, dev_id, i, d_hash[thr_id],
                                                    endiandata, pdata, hashOrder, start,
                                                    throughput, 0);
                                *hashes_done = 0;
                                return 0;
                        }
                        avian_stage_check(dev_id, i, hashOrder);
                        elem = hashOrder[i];
                        uint8_t algo64 = elem >= 'A' ? elem - 'A' + 10 : elem - '0';
                        uint8_t nextalgo = -1;

                        if (i < 15)
                        {
                                const char elem2 = hashOrder[i + 1];
                                nextalgo = elem2 >= 'A' ? elem2 - 'A' + 10 : elem2 - '0';
                        }
                        switch (algo64) {
                        case BLAKE:
                                if (i == 15 && !avian_no_final())
                                {
                                        quark_blake512_cpu_hash_64_final(thr_id, throughput, NULL, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {

                                        quark_blake512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                }

                                break;
                        case BMW:
                                if (i == 15 && !avian_no_final())
                                {
                                        quark_bmw512_cpu_hash_64_final(thr_id, throughput, NULL, d_hash[thr_id], d_resNonce[thr_id],((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        quark_bmw512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                }

                                break;
                        case GROESTL:
                                if (i == 15 && !avian_no_final())
                                {
                                        quark_groestl512_cpu_hash_64_final(thr_id, throughput,d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        quark_groestl512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                }
                                break;
                        case JH:
                                quark_jh512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                break;
                        case KECCAK:
                                //quark_keccak512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                quark_keccak512_cpu_hash_64(thr_id, throughput, NULL, d_hash[thr_id]); order++;
                                break;
                        case SKEIN:
                                if (i == 15 && !avian_no_final())
                                {
                                        quark_skein512_cpu_hash_64_final(thr_id, throughput, d_hash[thr_id], ((uint64_t *)ptarget)[3], d_resNonce[thr_id]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        quark_skein512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order++);
                                }
                                break;
                        case LUFFA:
                                if (i == 15 && !avian_no_final())
                                {
                                        x11_luffa512_cpu_hash_64_final(thr_id, throughput, d_hash[thr_id], ((uint64_t *)ptarget)[3], d_resNonce[thr_id]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x11_luffa512_cpu_hash_64_alexis(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        case CUBEHASH:
                                if (nextalgo == SHAVITE)
                                {
                                        x11_cubehash_shavite512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]); order++;
                                        i = i + 1;
                                }
                                else
                                {
                                        x11_cubehash512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        case SHAVITE:
                                if (i == 15 && !avian_no_final())
                                {
                                        x11_shavite512_cpu_hash_64_sp_final(thr_id, throughput, d_hash[thr_id], ((uint64_t *)ptarget)[3], d_resNonce[thr_id]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x11_shavite512_cpu_hash_64_sp(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        case SIMD:
                                if (!splitsimd)
                                {
                                        if (i == 15 && !avian_no_final())
                                        {
                                                x11_simd512_cpu_hash_64_final(thr_id, throughput, 0, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                                CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                                nonce0 = h_resNonce[thr_id][0];
                                                addstart = true;
                                        } else if (nextalgo == ECHO)
                                        {
                                                x16_simd_echo512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]);
                                                i = i + 1;
                                        }/*
                                        else if (nextalgo == WHIRLPOOL)
                                        {
                                                x16_simd_whirlpool512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]);
                                                i = i + 1;
                                        }*/
                                        else if (nextalgo == HAMSI)
                                        {
                                                x16_simd_hamsi512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]);
                                                i = i + 1;
                                        }/*
                                        else if (nextalgo == FUGUE)
                                        {
                                                x16_simd_fugue512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]);
                                                i = i + 1;
                                        }*/
                                        else
                                        {
                                                x11_simd512_cpu_hash_64(thr_id, throughput, pdata[19], NULL, d_hash[thr_id], order);
                                        }
                                }
                                else
                                {
                                        if (i == 15 && !avian_no_final())
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x11_simd512_cpu_hash_64_final(thr_id, throughput >> 4, (j >> 4)*(throughput >> 4), d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))), d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                                }
                                                CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                                nonce0 = h_resNonce[thr_id][0];
                                                addstart = true;
                                        }
                                        if (nextalgo == ECHO)
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x16_simd_echo512_cpu_hash_64(thr_id, throughput >> 4, d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))));
                                                }
                                                i = i + 1;
                                        }
                                        /*else if (nextalgo == WHIRLPOOL)
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x16_simd_whirlpool512_cpu_hash_64(thr_id, throughput >> 4, d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))));
                                                }
                                                i = i + 1;
                                        }*/
                                        else if (nextalgo == HAMSI)
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x16_simd_hamsi512_cpu_hash_64(thr_id, throughput >> 4, d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))));
                                                }
                                                i = i + 1;
                                        }/* Slower with cuda 9.2 / latest driver. 40% slower
                                        else if (nextalgo == FUGUE)
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x16_simd_fugue512_cpu_hash_64(thr_id, throughput >> 4, d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))));
                                                }
                                                
                                                i = i + 1;
                                        }*/
                                        else
                                        {
                                                for (int j = 0; j < 256; j += 16)
                                                {
                                                        x11_simd512_cpu_hash_64(thr_id, throughput >> 4, pdata[19], NULL, d_hash[thr_id] + (((throughput / 4)*j) / (sizeof(int))),order);
                                                }
                                        }
                                }
                                break;
                        case ECHO:
                                if (i == 15 && !avian_no_final())
                                {
                                        x11_echo512_cpu_hash_64_final_sp(thr_id, throughput, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x11_echo512_cpu_hash_64_sp(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        case HAMSI:
                                if (i == 15 && !avian_no_final())
                                {
                                        x13_hamsi512_cpu_hash_64_final(thr_id,throughput, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x13_hamsi512_cpu_hash_64(thr_id,throughput, d_hash[thr_id]);
                                }

                                break;
                        case FUGUE:
                                if (i == 15 && !avian_no_final())
                                {
                                        x13_fugue512_cpu_hash_64_final_sp(thr_id, throughput,d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x13_fugue512_cpu_hash_64_sp(thr_id, throughput, d_hash[thr_id]);
                                }
                                break;
                        case SHABAL:
                                if (i == 15 && !avian_no_final())
                                {
                                        x14_shabal512_cpu_hash_64_final_sp(thr_id, throughput, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x14_shabal512_cpu_hash_64_sp(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        case WHIRLPOOL:
                                if (i == 15 && !avian_no_final())
                                {
                                        x15_whirlpool_cpu_hash_64_final(thr_id, throughput, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x15_whirlpool_cpu_hash_64(thr_id, throughput, d_hash[thr_id]);
                                }
                                break;
                        case SHA512:
                                if (i == 15 && !avian_no_final())
                                {
                                        x17_sha512_cpu_hash_64_final(thr_id, throughput, d_hash[thr_id], d_resNonce[thr_id], ((uint64_t *)ptarget)[3]);
                                        CUDA_SAFE_CALL(cudaMemcpy(h_resNonce[thr_id], d_resNonce[thr_id], 2 * sizeof(uint32_t), cudaMemcpyDeviceToHost));
                                        nonce0 = h_resNonce[thr_id][0];
                                        addstart = true;
                                }
                                else
                                {
                                        x17_sha512_cpu_hash_64(thr_id, throughput, d_hash[thr_id]); order++;
                                }
                                break;
                        }
                }

                /* Stage 16, the complete chain. Only reachable with
                 * AVIAN_GPU_NO_FINAL=1, which is what leaves the last stage's
                 * hash in d_hash for this to read. */
                if (avian_trace_all() || avian_trace_stages() == 16)
                {
                        avian_trace_compare(thr_id, dev_id, 16, d_hash[thr_id],
                                            endiandata, pdata, hashOrder, start,
                                            throughput, 0);
                        *hashes_done = 0;
                        return 0;
                }

                avian_phase_check(dev_id, "the hash chain");

                if (!addstart)
                {
                        nonce0 = cuda_check_hash(thr_id, throughput, pdata[19], d_hash[thr_id]);
                }

                *hashes_done = pdata[19] - first_nonce + throughput;
                if (nonce0 != UINT32_MAX)
                {
                        if (addstart) nonce0 += start;

                        /* Check on the CPU before submitting, against this
                         * miner's own X16RT rather than a second
                         * implementation of it. That one is what
                         * --avian-selftest and avian/compare-with-avian-pow.sh
                         * already check against Avian Core, so a GPU result
                         * that disagrees with it is a kernel bug and must not
                         * reach a pool.
                         *
                         * endiandata holds the header as big-endian words, and
                         * be32enc of the GPU's nonce leaves word 19 in exactly
                         * the orientation x16r_hash expects: ccminer and this
                         * miner describe the same convention with the nonce
                         * integer byte-swapped between them, so the two
                         * cancel.
                         */
                        /* The miner verifies and submits. A candidate is
                         * only the device's opinion; what stands between a
                         * kernel defect and a bad share is the CPU hash, and
                         * that lives on the miner's side of this boundary. */
                        int found = 0;
                        if (found < max_out) out_nonces[found++] = nonce0;

                        /* A batch can hold a second solution, reported one of
                         * two ways depending on whether the last stage ran a
                         * _final kernel. Kept exactly as the original driver
                         * had it: the two paths count nonces in different
                         * frames, so conflating them would offer a nonce from
                         * the wrong place in the batch. */
                        if (addstart) {
                                uint32_t second = h_resNonce[thr_id][1];
                                if (second != UINT32_MAX && found < max_out) {
                                        out_nonces[found++] = second + start;
                                }
                        } else {
                                uint32_t second = cuda_check_hash_suppl(thr_id, throughput,
                                                                        start, d_hash[thr_id], 1);
                                if (second != 0 && second != UINT32_MAX && found < max_out) {
                                        out_nonces[found++] = second;
                                }
                        }
                        if (throughput_used) *throughput_used = throughput;
                        avian_batch_end(dev_id);
                        return found;
                }
                if (throughput_used) *throughput_used = throughput;
                avian_batch_end(dev_id);
                return 0;
        }
        return 0;
}
